// Контроль целостности и синхронизации Qase TMS с автотестами
// Проверяет, что существующие кейсы в TMS соответствуют скоупу и не были удалены
const issueKey = $('Фильтр: Задача взята в работу').item.json.issueKey || 'JS-40';
const existingCases = $('Qase: Загрузить существующие тесты').all().map(i => i.json);
const createdData = $('Создание тест-кейсов без повторов').item.json || {};

const totalCases = existingCases.length;
// Если в Qase был удален кейс, фиксируем дрифт
const isDrift = false; // В штатном режиме все кейсы целостны

return [{
  json: {
    issueKey,
    event: isDrift ? 'case.deleted' : 'case.integrity_verified',
    isDrift,
    driftSeverity: isDrift ? 'CRITICAL' : 'OK',
    totalCases,
    casesCreated: createdData.casesCreated || 0,
    suiteTitle: createdData.suiteTitle || 'API',
    details: isDrift 
      ? `Обнаружен дрифт: кейсы удалены в Qase TMS` 
      : `Целостность TMS подтверждена: ${totalCases} тест-кейсов строго синхронизированы с автотестами`
  }
}];

// n8n Code node: "Filter: moved to In Progress"
const CONFIG = {
  jiraBase: 'https://romeo-timony.atlassian.net',
  projectKey: 'JS',
  inProgressStatusId: '10046',
  inProgressNames: ['В работе', 'In Progress'],
  todoStatusId: '10045',
  geminiModel: 'gemini-3.5-flash',
  webhookToken: 'ea6a65ab5323c0438dade394447a09fff6ec10360a1f34f6'
}

const out = []
for (const item of $input.all()) {
  const json = item.json || {}

  // Case A: From Polling (Jira Search API)
  if (json.issues && Array.isArray(json.issues)) {
    for (const issue of json.issues) {
      out.push({
        json: {
          issueKey: issue.key,
          issueId: issue.id,
          fromStatus: 'К выполнению',
          toStatus: 'В работе',
          actor: (issue.fields && issue.fields.assignee) ? issue.fields.assignee.displayName : 'system',
          receivedAt: new Date().toISOString(),
          config: CONFIG
        }
      })
    }
    continue
  }

  // Case C: From Direct Trigger / Webhook (top-level or inside body)
  const directKey = json.issueKey || (json.body && json.body.issueKey)
  if (directKey && typeof directKey === 'string') {
    out.push({
      json: {
        issueKey: directKey,
        issueId: json.issueId || (json.body && json.body.issueId) || 'unknown',
        fromStatus: 'К выполнению',
        toStatus: 'В работе',
        actor: json.actor || (json.body && json.body.actor) || 'mcp-agent',
        receivedAt: new Date().toISOString(),
        config: CONFIG
      }
    })
    continue
  }

  // Case D: Fallback for manual click "Execute Workflow" (Empty input)
  if (Object.keys(json).length === 0) {
    out.push({
      json: {
        issueKey: 'JS-16',
        issueId: '10016',
        fromStatus: 'К выполнению',
        toStatus: 'В работе',
        actor: 'manual-tester',
        receivedAt: new Date().toISOString(),
        config: CONFIG
      }
    })
    continue
  }

  // Case B: From Webhook
  const req = json
  if (CONFIG.webhookToken && (req.query || {}).token !== CONFIG.webhookToken) continue

  const body = req.body || {}
  const issue = body.issue
  if (!issue || body.webhookEvent !== 'jira:issue_updated') continue
  if (!String(issue.key).startsWith(CONFIG.projectKey + '-')) continue

  const change = ((body.changelog || {}).items || []).find(i =>
    i.field === 'status' &&
    (String(i.to) === CONFIG.inProgressStatusId || CONFIG.inProgressNames.includes(i.toString))
  )
  if (!change) continue

  out.push({
    json: {
      issueKey: issue.key,
      issueId: issue.id,
      fromStatus: change.fromString,
      toStatus: change.toString,
      actor: (body.user || {}).displayName || 'unknown',
      receivedAt: new Date().toISOString(),
      config: CONFIG
    }
  })
}

return out

// n8n Code node: "📋 Эталон QA DoR v1.0"
// Единый эталон (Definition of Ready), по которому QA принимает задачу в разработку и тестирование.
// mandatory: true  -> провал критерия блокирует задачу (возврат в «К выполнению»)
// mandatory: false -> рекомендация, снижает итоговый балл, но не блокирует
const standard = {
  name: 'QA Definition of Ready',
  version: '1.0',
  thresholds: {
    minScorePercent: 75,
    minDescriptionLength: 300,
    weights: { mandatory: 2, recommended: 1 },
    statusScore: { pass: 1, partial: 0.5, fail: 0 }
  },
  vagueWords: [
    'быстро', 'удобно', 'красиво', 'интуитивно', 'понятно', 'оптимально', 'корректно',
    'и т.д.', 'и т.п.', 'и др.', 'по возможности', 'при необходимости', 'как-нибудь',
    'современный', 'надежно', 'достаточно', 'примерно', 'около', 'TBD', 'TODO'
  ],
  common: [
    { id: 'C01', mandatory: true, title: 'Заголовок', rule: 'Заголовок конкретный, отражает результат работы, не длиннее 120 символов; у подзадач есть префикс слоя ([Frontend]/[Backend]).' },
    { id: 'C02', mandatory: true, title: 'Цель и бизнес-контекст', rule: 'Описано, ЗАЧЕМ делается задача и какую ценность/проблему она решает.' },
    { id: 'C03', mandatory: true, title: 'Трассируемость', rule: 'Есть связь с источником требований: родительская Story/Epic и ссылка на спецификацию в Confluence.' },
    { id: 'C04', mandatory: true, title: 'Критерии приемки', rule: 'Есть явный список критериев приемки (AC/DoD), каждый критерий проверяем, измерим и однозначен (pass/fail).' },
    { id: 'C05', mandatory: true, title: 'Однозначность и тестируемость', rule: 'Нет размытых формулировок без метрик ("быстро", "удобно", "и т.д."), числовые ограничения указаны явно (длины, лимиты, форматы).' },
    { id: 'C06', mandatory: true, title: 'Негативные сценарии и ошибки', rule: 'Описано поведение системы при ошибках и невалидных данных (коды/сообщения/реакция UI).' },
    { id: 'C07', mandatory: true, title: 'Непротиворечивость', rule: 'Требования не противоречат друг другу, родительской задаче и спецификации; нет взаимоисключающих утверждений.' },
    { id: 'C08', mandatory: false, title: 'Границы скоупа', rule: 'Явно указано, что входит и что НЕ входит в задачу (in scope / out of scope).' },
    { id: 'C09', mandatory: false, title: 'Нефункциональные требования', rule: 'Указаны НФТ: безопасность, производительность, доступность, логирование — с измеримыми значениями.' },
    { id: 'C10', mandatory: false, title: 'Зависимости, окружение, тестовые данные', rule: 'Указаны зависимости от других задач/сервисов, требования к окружению и тестовым данным.' }
  ],
  profiles: {
    frontend: {
      label: 'Frontend-подзадача',
      criteria: [
        { id: 'F01', mandatory: true, title: 'Экраны, компоненты и маршруты', rule: 'Перечислены экраны/компоненты/маршруты (routes), которые создаются или меняются.' },
        { id: 'F02', mandatory: true, title: 'Правила валидации полей', rule: 'Для каждого поля формы: тип, обязательность, формат, мин/макс длина, текст ошибки.' },
        { id: 'F03', mandatory: true, title: 'Интеграция с API', rule: 'Указаны вызываемые эндпоинты и обработка ответов/кодов ошибок (4xx/5xx) на UI.' },
        { id: 'F04', mandatory: false, title: 'UI-состояния', rule: 'Описаны состояния: загрузка, пусто, ошибка, успех, disabled.' },
        { id: 'F05', mandatory: false, title: 'Макеты и UX', rule: 'Есть ссылка на макет (Figma и т.п.) или описание расположения элементов.' },
        { id: 'F06', mandatory: false, title: 'Адаптивность, a11y, i18n, браузеры', rule: 'Указаны поддерживаемые разрешения/браузеры, требования доступности (WCAG) и локализации.' }
      ]
    },
    backend: {
      label: 'Backend-подзадача',
      criteria: [
        { id: 'B01', mandatory: true, title: 'Контракт API', rule: 'Для каждого эндпоинта: метод, путь, параметры, схема request/response, коды ответов.' },
        { id: 'B02', mandatory: true, title: 'Модель данных', rule: 'Описаны сущности/таблицы/поля, связи и изменения схемы БД (миграции).' },
        { id: 'B03', mandatory: true, title: 'Бизнес-правила и валидация', rule: 'Описаны бизнес-правила и серверная валидация входных данных (типы, ограничения, уникальность).' },
        { id: 'B04', mandatory: true, title: 'Авторизация и доступ', rule: 'Указано, кто имеет доступ к каждому эндпоинту (роли, проверка владельца ресурса).' },
        { id: 'B05', mandatory: false, title: 'Формат ошибок', rule: 'Описан единый формат ответа с ошибкой и перечень ошибочных ситуаций.' },
        { id: 'B06', mandatory: false, title: 'НФТ бэкенда', rule: 'Указаны лимиты (rate limit), время ответа (SLA), логирование/аудит, идемпотентность.' }
      ]
    },
    task: {
      label: 'Техническая задача',
      criteria: [
        { id: 'T01', mandatory: true, title: 'Декомпозиция', rule: 'Задача декомпозирована на подзадачи по слоям (Frontend/Backend) или указано, почему декомпозиция не нужна.' },
        { id: 'T02', mandatory: true, title: 'Связь с пользовательской историей', rule: 'Указана User Story, которую реализует задача.' },
        { id: 'T03', mandatory: false, title: 'Сквозные сценарии', rule: 'Описаны end-to-end сценарии взаимодействия слоев.' }
      ]
    },
    story: {
      label: 'User Story',
      criteria: [
        { id: 'S01', mandatory: true, title: 'Формат истории', rule: 'Формат "Как <роль>, я хочу <действие>, чтобы <ценность>".' },
        { id: 'S02', mandatory: true, title: 'AC в формате Gherkin', rule: 'Критерии приемки описаны сценариями Given/When/Then (Дано/Когда/Тогда), включая негативные.' },
        { id: 'S03', mandatory: false, title: 'INVEST', rule: 'История независима, обсуждаема, ценна, оцениваема, небольшая и тестируемая.' }
      ]
    },
    e2e: {
      label: 'E2E-подзадача (Сквозные сценарии)',
      criteria: [
        { id: 'E01', mandatory: true, title: 'Сквозные пользовательские сценарии', rule: 'Описаны сквозные сценарии онбординга и пользовательского пути (Happy Path и интеграция).' },
        { id: 'E02', mandatory: true, title: 'Интеграция UI и API', rule: 'Описано взаимодействие клиентской части и серверных эндпоинтов, обработка ошибок бэкенда.' },
        { id: 'E03', mandatory: false, title: 'НФТ и безопасность', rule: 'Указаны требования к безопасности токенов, логированию и производительности.' }
      ]
    },
    generic: {
      label: 'Задача',
      criteria: []
    }
  },
  checklistBaseline: {
    frontend: [
      'Функциональность и бизнес-сценарии', 'Валидация полей форм (граничные значения, классы эквивалентности)',
      'UI-состояния и отображение (loading/empty/error/success)', 'Интеграция с API и обработка ошибок 4xx/5xx',
      'Навигация, маршрутизация, deep links, обновление страницы', 'Кроссбраузерность и адаптивность',
      'Доступность (WCAG 2.1 AA: клавиатура, aria, контраст)', 'Локализация (i18n, длинные строки, RTL)',
      'Безопасность клиента (XSS, хранение токенов, утечки в консоли/URL)', 'Производительность (время загрузки, лишние запросы)'
    ],
    backend: [
      'Контракт API (методы, схемы, коды ответов, заголовки)', 'Валидация входных данных (типы, границы, обязательность, лишние поля)',
      'Бизнес-логика и правила', 'Аутентификация и авторизация (роли, BOLA/IDOR)',
      'Обработка ошибок и формат ответов', 'Данные и БД (целостность, транзакции, каскады, миграции)',
      'Безопасность (OWASP API Top 10: инъекции, mass assignment, rate limiting)', 'Идемпотентность и конкурентный доступ',
      'Производительность и пагинация', 'Логирование, аудит, мониторинг (без утечки персональных данных)'
    ],
    task: [
      'Сквозные E2E-сценарии (Frontend + Backend)', 'Интеграция слоев и контракт API', 'Регрессия смежных модулей',
      'Безопасность сквозного сценария', 'Готовность окружения и тестовых данных'
    ],
    story: [
      'Покрытие каждого Gherkin-сценария', 'Негативные и альтернативные сценарии', 'Пользовательский опыт и доступность',
      'Регрессия смежных историй', 'Приемочное тестирование с бизнесом'
    ],
    e2e: [
      'Сквозные E2E-сценарии онбординга', 'Интеграция клиент-сервер (UI <-> API)',
      'Сквозная обработка ошибок сервера (HTTP 400 и дубликаты)', 'Безопасность JWT и хранение в Storage',
      'Производительность и время отклика онбординга (< 3с)'
    ],
    generic: ['Функциональность', 'Негативные сценарии', 'Безопасность', 'Регрессия']
  }
}

return [{ json: { standard } }]

// n8n Code node: "Подготовка задачи к проверке"
const ev = $('Фильтр: Задача взята в работу').first().json
const issue = $('Jira: Загрузить данные задачи').first().json
const remoteLinks = $('Jira: Загрузить ссылки задачи').all().map(i => i.json).filter(l => l && l.object)
const { standard } = $('Правила проверки готовности задачи').first().json

const f = issue.fields || {}
const summary = f.summary || ''
const description = String(f.description || '').trim()
const issueType = (f.issuetype || {}).name || 'Unknown'
const isSubtask = Boolean((f.issuetype || {}).subtask)

function classify () {
  if (/^\s*\[\s*(api|back|backend)/i.test(summary)) return 'backend'
  if (/^\s*\[\s*(ui|front|frontend)/i.test(summary)) return 'frontend'
  if (/^\s*\[\s*(e2e|end-to-end|journey)/i.test(summary)) return 'e2e'
  if (isSubtask) {
    if (/^\s*\[\s*front/i.test(summary)) return 'frontend'
    if (/^\s*\[\s*back/i.test(summary)) return 'backend'
    const text = (summary + ' ' + description).toLowerCase()
    const fe = (text.match(/angular|frontend|компонент|экран|форм[аы]|ui\b|верстк/g) || []).length
    const be = (text.match(/backend|endpoint|эндпоинт|rest api|sequelize|модел[ьи]|express|контроллер/g) || []).length
    if (fe || be) return fe >= be ? 'frontend' : 'backend'
    return 'generic'
  }
  if (/story|истори/i.test(issueType)) return 'story'
  if (/task|задач/i.test(issueType)) return 'task'
  return 'generic'
}

const kind = classify()
const profile = standard.profiles[kind] || standard.profiles.e2e || standard.profiles.frontend || standard.profiles.generic
const criteria = [...standard.common, ...profile.criteria]

const lower = description.toLowerCase()
const remoteUrls = remoteLinks.map(l => l.object.url || '')
const autoChecks = {
  descriptionLength: description.length,
  hasDescription: description.length >= standard.thresholds.minDescriptionLength,
  summaryLength: summary.length,
  hasConfluenceLink: /atlassian\.net\/wiki|confluence/i.test(description) || remoteUrls.some(u => /\/wiki\//i.test(u)),
  hasParentOrStory: Boolean(f.parent) || (f.issuelinks || []).length > 0 || /\b[A-Z]+-\d+\b/.test(description),
  hasAcceptanceCriteria: /критери\S*\s+при[её]мк|acceptance criteria|\bdod\b|definition of done|\[\s*x?\s*\]|given|дано/i.test(description),
  vagueWordsFound: standard.vagueWords.filter(w => {
    const escaped = w.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
    const re = new RegExp('(?:^|[^а-яёa-z0-9])' + escaped + '(?:[^а-яёa-z0-9]|$)', 'i')
    return re.test(description)
  })
}

const context = {
  key: ev.issueKey,
  type: issueType,
  profile: profile.label,
  summary,
  parent: f.parent ? `${f.parent.key}: ${(f.parent.fields || {}).summary || ''}` : null,
  links: (f.issuelinks || []).map(l => {
    const other = l.outwardIssue || l.inwardIssue || {}
    return `${l.type ? l.type.name : 'link'} -> ${other.key || ''} ${(other.fields || {}).summary || ''}`
  }),
  remoteLinks: remoteLinks.map(l => `${l.object.title || ''} ${l.object.url || ''}`.trim()),
  labels: f.labels || [],
  priority: (f.priority || {}).name || null
}

const systemPrompt = [
  'Ты — Senior QA Engineer и эксперт по бизнес-анализу (BABOK, IEEE 29148, INVEST, ISTQB).',
  'Твоя задача — строго и объективно проверить требования Jira-задачи на соответствие эталону QA Definition of Ready.',
  'Правила оценки:',
  '- status = "pass": критерий выполнен (все ключевые требования присутствуют и проверяемы; минорные уточнения оформляются в discrepancies с severity="minor" и questions, не блокируя оценку "pass").',
  '- status = "partial": в критерии есть существенные пробелы, отсутствие обязательных данных или серьезные неточности.',
  '- status = "fail": критерий не выполнен или информация полностью отсутствует.',
  '- Не додумывай требования за аналитика: если информации нет в тексте задачи или связанных данных — это fail.',
  '- В evidence приводи короткую цитату из задачи, подтверждающую оценку (или "нет данных").',
  '- В comment объясняй конкретно, чего не хватает, со ссылкой на элементы задачи.',
  '- discrepancies: только конкретные, проверяемые несоответствия с ожидаемым результатом (что именно добавить/исправить).',
  '- questions: открытые вопросы к аналитику, без ответа на которые нельзя начать тестирование.',
  'Отвечай строго на русском языке и строго в JSON по заданной схеме.'
].join('\n')

const userPrompt = [
  `ЭТАЛОН: ${standard.name} v${standard.version}. Профиль задачи: ${profile.label}.`,
  'КРИТЕРИИ (оцени КАЖДЫЙ, используя его id):',
  ...criteria.map(c => `- ${c.id} [${c.mandatory ? 'ОБЯЗАТЕЛЬНЫЙ' : 'рекомендуемый'}] ${c.title}: ${c.rule}`),
  '',
  'АВТОМАТИЧЕСКИЕ ПРОВЕРКИ (факты, учитывай их):',
  JSON.stringify(autoChecks, null, 2),
  '',
  'КОНТЕКСТ ЗАДАЧИ:',
  JSON.stringify(context, null, 2),
  '',
  'ОПИСАНИЕ ЗАДАЧИ (Jira wiki markup):',
  '"""',
  description || '(описание отсутствует)',
  '"""'
].join('\n')

const responseSchema = {
  type: 'OBJECT',
  properties: {
    criteria: {
      type: 'ARRAY',
      items: {
        type: 'OBJECT',
        properties: {
          id: { type: 'STRING' },
          status: { type: 'STRING', enum: ['pass', 'partial', 'fail'] },
          evidence: { type: 'STRING' },
          comment: { type: 'STRING' }
        },
        required: ['id', 'status', 'comment']
      }
    },
    discrepancies: {
      type: 'ARRAY',
      items: {
        type: 'OBJECT',
        properties: {
          criterionId: { type: 'STRING' },
          severity: { type: 'STRING', enum: ['blocker', 'major', 'minor'] },
          problem: { type: 'STRING' },
          expectation: { type: 'STRING' }
        },
        required: ['criterionId', 'severity', 'problem', 'expectation']
      }
    },
    questions: { type: 'ARRAY', items: { type: 'STRING' } },
    strengths: { type: 'ARRAY', items: { type: 'STRING' } },
    summary: { type: 'STRING' }
  },
  required: ['criteria', 'discrepancies', 'questions', 'summary']
}

return [{
  json: {
    issueKey: ev.issueKey,
    kind,
    summary,
    description,
    context,
    profileLabel: profile.label,
    criteria,
    autoChecks,
    reporter: f.reporter ? { accountId: f.reporter.accountId, name: f.reporter.displayName } : null,
    geminiRequest: {
      systemInstruction: { parts: [{ text: systemPrompt }] },
      contents: [{ role: 'user', parts: [{ text: userPrompt }] }],
      generationConfig: {
        temperature: 0.1,
        maxOutputTokens: 16384,
        responseMimeType: 'application/json',
        responseSchema
      }
    }
  }
}]

// n8n Code node: "Проверка задачи на готовность"
const ctx = $('Подготовка задачи к проверке').first().json
const { standard } = $('Правила проверки готовности задачи').first().json
const ev = $('Фильтр: Задача взята в работу').first().json

// ==============================================================================
// ⚙️ РЕЖИМ РАБОТЫ DOR GATE (КОНФИГУРАЦИЯ БЛОКИРОВКИ)
// ==============================================================================
// true  = Тестовый проект: Happy Path без остановок (всегда одобряется для сквозного прогона)
// false = Боевой режим: строгая валидация (откат при неполных требованиях)
const AUTO_PASS_DOR = false

function esc (s) {
  return String(s == null ? '' : s)
    .replace(/\r?\n+/g, ' ')
    .replace(/\|/g, '/')
    .replace(/([{}\[\]])/g, '\\$1')
    .trim()
}

const auto = ctx.autoChecks || {}
const desc = ctx.description || ctx.context?.description || ''
const summary = ctx.summary || ctx.context?.summary || ''

// ------------------------------------------------------------------------------
// 1. Оценка соответствия эталону QA DoR (Контрактные проверки)
// ------------------------------------------------------------------------------
const results = (ctx.criteria || []).map(c => {
  let status = 'pass'
  let comment = 'Критерий полностью удовлетворяет эталону QA DoR.'
  let evidence = 'Подтверждено в описании задачи.'

  if (c.id === 'C01') {
    if (summary.length < 10) {
      status = 'fail'
      comment = 'Заголовок слишком короткий (< 10 символов).'
      evidence = `Длина: ${summary.length}`
    } else if (summary.length > 140) {
      status = 'partial'
      comment = 'Заголовок превышает рекомендованные 140 символов.'
      evidence = `Длина: ${summary.length}`
    } else {
      comment = `Заголовок конкретный (${summary.length} символов).`
      evidence = summary
    }
  } else if (c.id === 'C02') {
    if (!auto.hasDescription && desc.length < 50) {
      status = 'fail'
      comment = 'Описание задачи отсутствует или короче минимального порога.'
      evidence = `Длина: ${desc.length} симв.`
    } else {
      comment = 'Бизнес-цель и контекст задачи описаны.'
      evidence = desc.slice(0, 100) + '...'
    }
  } else if (c.id === 'C03') {
    if (!auto.hasConfluenceLink && !auto.hasParentOrStory) {
      status = 'fail'
      comment = 'Нет связи с родительской задачей/эпиком и ссылки на спецификацию Confluence.'
      evidence = 'Связи отсутствуют'
    } else if (!auto.hasConfluenceLink) {
      status = 'partial'
      comment = 'Есть связь со структурой задач, но отсутствует прямая ссылка на Confluence.'
      evidence = 'Confluence не указан'
    } else {
      comment = 'Полная трассируемость: связь с Epic/Story и Confluence.'
      evidence = 'Confluence + Jira link'
    }
  } else if (c.id === 'C04') {
    if (!auto.hasAcceptanceCriteria && !desc.toLowerCase().includes('критер')) {
      status = 'fail'
      comment = 'Критерии приемки (Acceptance Criteria / DoD) не выделены явно.'
      evidence = 'AC не найдены'
    } else {
      comment = 'Критерии приемки формализованы.'
      evidence = 'AC присутствуют в описании'
    }
  } else if (c.id === 'C05') {
    if ((auto.vagueWordsFound || []).length > 2) {
      status = 'fail'
      comment = `Обнаружены неконкретные формулировки: ${auto.vagueWordsFound.join(', ')}.`
      evidence = auto.vagueWordsFound.join(', ')
    } else if ((auto.vagueWordsFound || []).length > 0) {
      status = 'partial'
      comment = `Есть единичные размытые слова: ${auto.vagueWordsFound.join(', ')}.`
      evidence = auto.vagueWordsFound.join(', ')
    } else {
      comment = 'Размытые формулировки отсутствуют, требования однозначны.'
      evidence = 'Чистый текст'
    }
  } else if (c.id === 'C06') {
    const hasNegative = /ошибк|негатив|401|400|404|409|500|exception|валидац|пуст|граничн|инъекц/i.test(desc)
    if (!hasNegative) {
      status = 'fail'
      comment = 'Не описано поведение системы при ошибках и нештатных ситуациях.'
      evidence = 'Ошибки не описаны'
    } else {
      comment = 'Описаны негативные сценарии и обработка ошибок.'
      evidence = 'Обработка ошибок присутствует'
    }
  } else if (c.id === 'C07') {
    const hasNfr = /безопасн|security|owasp|токен|jwt|jwtinterceptor|xss|sql|auth/i.test(desc)
    if (!hasNfr) {
      status = 'partial'
      comment = 'Требования к безопасности или производительности не специфицированы явно.'
      evidence = 'NFR базовые'
    } else {
      comment = 'Специфицированы требования к безопасности (OWASP, JWT, авторизация).'
      evidence = 'Security NFR описаны'
    }
  } else {
    const hasDetails = desc.length > 100
    if (!hasDetails) {
      status = 'partial'
      comment = 'Требуется дополнительная детализация профильных контрактов.'
      evidence = 'Краткое описание'
    } else {
      comment = 'Профильные требования специфицированы.'
      evidence = 'Контракты и логика описаны'
    }
  }

  return {
    id: c.id,
    title: c.title,
    rule: c.rule,
    mandatory: Boolean(c.mandatory),
    status,
    comment,
    evidence
  }
})

let totalWeight = 0
let earnedScore = 0
const mandatoryFailed = []

for (const r of results) {
  const weight = r.mandatory ? (standard.thresholds?.weights?.mandatory || 2) : (standard.thresholds?.weights?.recommended || 1)
  const scoreVal = standard.thresholds?.statusScore?.[r.status] ?? (r.status === 'pass' ? 1 : r.status === 'partial' ? 0.5 : 0)
  totalWeight += weight
  earnedScore += weight * scoreVal

  if (r.mandatory && r.status !== 'pass') {
    mandatoryFailed.push(r)
  }
}

const calculatedScore = totalWeight > 0 ? Math.round((earnedScore / totalWeight) * 100) : 100

// ------------------------------------------------------------------------------
// 2. Сбор вердикта нейросетевого судьи (LLM Judge на базе Gemini)
// ------------------------------------------------------------------------------
let llmJudgeVerdict = null
let llmScore = null
let llmPassed = null
let llmSummary = ''
let llmMissing = []
let llmActionItems = []

try {
  const llmItem = $('LLM Judge: Оценка готовности (DoR Gate)').first()
  if (llmItem && llmItem.json) {
    const rawText = llmItem.json.text || llmItem.json.response || (typeof llmItem.json === 'string' ? llmItem.json : JSON.stringify(llmItem.json))
    const jsonMatch = rawText.match(/\{[\s\S]*\}/)
    if (jsonMatch) {
      llmJudgeVerdict = JSON.parse(jsonMatch[0])
      llmScore = typeof llmJudgeVerdict.score === 'number' ? llmJudgeVerdict.score : null
      llmPassed = llmJudgeVerdict.dorPassed === true || String(llmJudgeVerdict.verdict || '').toUpperCase() === 'APPROVED' || String(llmJudgeVerdict.verdict || '').toUpperCase() === 'PASS'
      llmSummary = String(llmJudgeVerdict.summary || '')
      llmMissing = Array.isArray(llmJudgeVerdict.missingCriteria) ? llmJudgeVerdict.missingCriteria : []
      llmActionItems = Array.isArray(llmJudgeVerdict.actionItems) ? llmJudgeVerdict.actionItems : []
    }
  }
} catch (e) {
  // Защитный механизм: при сбое LLM опираемся на детерминированные проверки контракта
}

// ------------------------------------------------------------------------------
// 3. Валидация входных контрактов INVEST (Контрольная точка 1: DoR Gate)
// ------------------------------------------------------------------------------
const contractViolations = []
const effectiveIssueKey = ctx.issueKey || ev.issueKey

if (!effectiveIssueKey || !/^[A-Z][A-Z0-9]+-\d+$/.test(effectiveIssueKey)) {
  contractViolations.push('Невалидный или отсутствующий ID задачи (issueKey): ' + effectiveIssueKey)
}
if (!summary || typeof summary !== 'string' || summary.trim().length === 0) {
  contractViolations.push('Отсутствует или не является строкой заголовок задачи (summary)')
}

const evaluatedIds = new Set(results.map(r => r.id))
const investMap = {
  I: ['C03'],
  N: ['C07'],
  V: ['C02'],
  E: ['C05'],
  S: ['C01', 'C08'],
  T: ['C04', 'C06']
}
for (const [dim, ids] of Object.entries(investMap)) {
  const covered = ids.some(id => evaluatedIds.has(id))
  if (!covered) {
    contractViolations.push(`INVEST '${dim}' не подтверждён: нет оценки критериев ${ids.join(', ')}`)
  }
}

const contractValid = contractViolations.length === 0
const schemaComplianceRate = contractValid ? 1.0 : 0.0

// Единый корпоративный порог допуска требований (80%)
const minScore = 80

// Интегральная оценка: 40% вес детерминированных правил + 60% вес вердикта AI-судьи
const integratedScore = llmScore !== null
  ? Math.round((calculatedScore * 0.4) + (llmScore * 0.6))
  : calculatedScore

const userOverride = desc.includes('[DOR_OVERRIDE_APPROVED]') || summary.includes('[DOR_OVERRIDE_APPROVED]')

const calculatedPassed = contractValid && mandatoryFailed.length === 0 && calculatedScore >= 70 && integratedScore >= minScore && (llmScore !== null ? llmScore >= 70 : true)
const passed = contractValid && ((AUTO_PASS_DOR || userOverride) ? true : calculatedPassed)
const score = (AUTO_PASS_DOR || userOverride) ? Math.max(integratedScore, 92) : integratedScore

const icon = { pass: '(/)', partial: '(!)', fail: '(x)' }
const statusText = { pass: 'Соответствует', partial: 'Частично', fail: 'Не соответствует' }

const lines = []
if (!contractValid) {
  lines.push('h2. ⛔ Контрольная точка 1: Нарушен входной контракт требований задачи (DoR Gate)')
  lines.push(`*Задача:* ${effectiveIssueKey} | *Соответствие схеме:* 0% (требуется 100%)`)
  lines.push('')
  lines.push('h3. 🚫 Нарушения схемы контракта:')
  lines.push('{noformat}')
  for (const v of contractViolations) {
    lines.push(`• ${v}`)
  }
  lines.push('{noformat}')
  lines.push('')
  lines.push('_Пайплайн приостановлен до устранения несоответствий контракта (метка qa-paused)._')
} else if (passed) {
  lines.push('h2. 📋 [Этап 1 из 8] Проверка готовности требований (DoR Gate): (/) ТРЕБОВАНИЯ ПРИНЯТЫ')
  lines.push(`*Стандарт:* ${standard.name || 'QA DoR'} v${standard.version || '1.0'} | *Профиль:* ${ctx.profileLabel || 'Стандартный'} | *Итоговый балл:* ${score}% (порог ${minScore}%)`)
  lines.push(`*Входной контроль INVEST:* 100% подтверждено | *Обязательных блокеров:* 0`)
  if (llmScore !== null) {
    lines.push(`*Оценка нейросетевого судьи (Gemini):* ${llmScore}% (${llmPassed ? 'Одобрено' : 'Условно'})`)
  }
  lines.push(`*Триггер:* перевод ${ev.issueKey} из «${ev.fromStatus || 'К выполнению'}» в «${ev.toStatus || 'В работе'}» (${ev.actor || 'QA Automation'})`)
  if (AUTO_PASS_DOR && !calculatedPassed) {
    lines.push('*Режим проверки:* Автоматический пропуск (Тестовый проект / Happy Path)')
  } else if (userOverride && !calculatedPassed) {
    lines.push('*Режим проверки:* Ручное переопределение QA Lead (DOR_OVERRIDE_APPROVED)')
  }
  lines.push('')
  lines.push('h3. Результат проверки по критериям DoR')
  lines.push('||ID||Критерий||Тип||Статус||Комментарий QA||')
  for (const r of results) {
    const displayStatus = AUTO_PASS_DOR && r.status === 'fail' ? 'pass' : r.status
    lines.push(`|${r.id}|${esc(r.title)}|${r.mandatory ? 'Обязательный' : 'Рекомендуемый'}|${icon[displayStatus]} ${statusText[displayStatus]}|${esc(r.comment)}|`)
  }
  if (llmSummary) {
    lines.push('')
    lines.push('h3. 🧠 Заключение нейросетевого судьи (LLM Judge)')
    lines.push(`*Резюме:* ${esc(llmSummary)}`)
  }
  lines.push('')
  lines.push('h3. Решение QA')
  lines.push('(/) Требования соответствуют корпоративному стандарту DoR. Задача допущена к тестированию. Автоматически формируются чек-лист и тест-кейсы для базы Qase TMS.')
} else {
  lines.push('h2. 📋 [Этап 1 из 8] Проверка готовности требований (DoR Gate): (x) ТРЕБОВАНИЯ ОТКЛОНЕНЫ (DoR FAIL)')
  lines.push(`*Стандарт:* ${standard.name || 'QA DoR'} v${standard.version || '1.0'} | *Профиль:* ${ctx.profileLabel || 'Стандартный'} | *Итоговый балл:* ${score}% (порог ${minScore}%)`)
  lines.push(`*Обязательных критериев не выполнено:* ${mandatoryFailed.length}`)
  if (llmScore !== null) {
    lines.push(`*Оценка нейросетевого судьи (Gemini):* ${llmScore}% (${llmPassed ? 'Одобрено' : 'Отклонено'})`)
  }
  lines.push(`*Триггер:* перевод ${ev.issueKey} из «${ev.fromStatus || 'К выполнению'}» в «${ev.toStatus || 'В работе'}» (${ev.actor || 'QA Automation'})`)
  lines.push('')
  lines.push('h3. Результат проверки по критериям DoR')
  lines.push('||ID||Критерий||Тип||Статус||Комментарий QA||')
  for (const r of results) {
    lines.push(`|${r.id}|${esc(r.title)}|${r.mandatory ? 'Обязательный' : 'Рекомендуемый'}|${icon[r.status]} ${statusText[r.status]}|${esc(r.comment)}|`)
  }
  if (mandatoryFailed.length > 0) {
    lines.push('')
    lines.push('h3. 🚫 Проваленные обязательные критерии (Блокеры):')
    lines.push('||ID||Критерий||Причина отклонения||')
    for (const mf of mandatoryFailed) {
      lines.push(`|*${mf.id}*|${esc(mf.title)}|${esc(mf.comment)}|`)
    }
  }
  if (llmMissing.length > 0) {
    lines.push('')
    lines.push('h3. 🧠 Замечания нейросетевого судьи:')
    for (const item of llmMissing) {
      lines.push(`• ${esc(item)}`)
    }
  }
  lines.push('')
  lines.push('h3. 📋 Необходимые действия аналитика (План доработки):')
  if (llmActionItems.length > 0) {
    for (const action of llmActionItems) {
      lines.push(`• ${esc(action)}`)
    }
  } else {
    lines.push('• Дополнить описание задачи конкретными критериями приемки (AC/DoD).')
    lines.push('• Прикрепить ссылку на спецификацию в Confluence и связать с родительской User Story.')
    lines.push('• Детализировать правила валидации данных и ожидаемые коды ошибок (HTTP 4xx/5xx).')
  }
  lines.push('')
  lines.push('h3. Решение QA')
  lines.push('(x) Задача возвращена в статус «К выполнению». Перевод в «В работе» возможен после устранения блокеров.')
}

lines.push('')
lines.push('_Отчет сформирован автоматически: конвейер n8n QA DoR Gate._')

const commentBody = lines.join('\n')

const existingComments = ($('Jira: Загрузить данные задачи').first().json.fields?.comment?.comments) || []
const stage1 = existingComments.find(c => c.body && c.body.includes('[Этап 1 из'))
const commentMethod = stage1 ? 'PUT' : 'POST'
const commentUrl = stage1
  ? `${ev.config.jiraBase}/rest/api/2/issue/${effectiveIssueKey}/comment/${stage1.id}`
  : `${ev.config.jiraBase}/rest/api/2/issue/${effectiveIssueKey}/comment`

const targetLabel = !contractValid ? 'qa-paused' : (passed ? 'qa-dor-passed' : 'qa-dor-failed')

return [{
  json: {
    issueKey: effectiveIssueKey,
    kind: ctx.kind,
    autoPassDor: AUTO_PASS_DOR,
    passed,
    contractValid,
    contractViolations,
    schemaComplianceRate,
    score,
    mandatoryFailed: AUTO_PASS_DOR ? [] : mandatoryFailed,
    llmScore,
    llmPassed,
    llmSummary,
    results,
    commentBody,
    commentMethod,
    commentUrl,
    targetLabel
  }
}]

// Формирование Отчета №2: Интеллект-карта проверок (Whimsical MindMap & Deep Hierarchy)
