  lines.push(`**** 🟢 [L4] Успешная привязка SecurityQuestionId к новому пользователю -> [L5] HTTP 201 Created [P1 | Smoke]`);
  lines.push(`**** 🔴 [L4] Несуществующий SecurityQuestionId (ID=999999) -> [L5] HTTP 400/404/500 [P1 | Integrity]`);
