    lines.push('|*NFR-UI-03*|Доступность интерфейса: навигация по полям формы регистрации клавишей Tab (WCAG 2.1 AA)|[TC-FE-12|https://app.qase.io/case/JS-12]|Доступность формы регистрации по клавиатуре (Tab Navigation)|Accessibility / a11y|E2E (Playwright)|(/) Покрыто (100%)|')
  }

  lines.push('')
  lines.push('h3. 🛡️ Покрытие нефункциональных требований (NFR & Quality Gates):')
  if (isBackend) {
    lines.push('* *OWASP API Security Top 10:* Broken Authentication (API1), Broken Object Level Authorization (API2), Injection (API8) — полностью закрыты кейсами JS-84, JS-86, JS-87, JS-89, JS-92.')
    lines.push('* *Data Integrity & Encryption:* Хеширование паролей и ответов на контрольные вопросы в SQLite проверяется кейсами JS-81, JS-88, JS-90.')
    lines.push('* *Производительность:* 100% тест-кейсов выполняются на уровне API (In-Memory Supertest), обеспечивая прогон регресса за секунды в CI/CD пайплайне.')
  } else if (kind === 'e2e') {
    lines.push('|*AC-E2E-01*|Happy Path: Полный цикл онбординга (регистрация -> логин -> витрина)|[TC-E2E-01]|Полный приемочный цикл онбординга нового покупателя: регистрация, вход и переход к покупкам|Smoke / Critical|E2E (Playwright)|(/) Покрыто (100%)|')
    lines.push('|*AC-E2E-02*|Интеграция: Консистентность данных между UI и API (POST /rest/user/login)|[TC-E2E-02]|Сквозная консистентность сессии и проверка сохранения Bearer JWT в Web Storage|Integration / Session|E2E (Playwright)|(/) Покрыто (100%)|')
    lines.push('|*AC-E2E-03*|Интеграция / Негативный: Сквозная обработка дубликата Email (HTTP 400 и UI Notification)|[TC-E2E-03]|Сквозная обработка дубликата Email при регистрации (HTTP 400 и UI Notification)|Negative / Functional|E2E (Playwright)|(/) Покрыто (100%)|')
    lines.push('|*AC-E2E-04*|Безопасность: Сквозное восстановление пароля по секретному вопросу|[TC-E2E-04]|Сквозной сценарий сброса и восстановления пароля по секретному вопросу|Security / Recovery|E2E (Playwright)|(/) Покрыто (100%)|')
    lines.push('|*NFR-E2E-01*|Безопасность / OWASP: Хранение Bearer токенов в localStorage, маскирование паролей|[TC-E2E-02]|Сквозная консистентность сессии и проверка сохранения Bearer JWT в Web Storage|Security / OWASP|E2E (Playwright)|(/) Покрыто (100%)|')
    lines.push('|*NFR-E2E-02*|Производительность: Онбординг завершается быстрее 3 секунд (SLA)|[TC-E2E-05]|Валидация SLA производительности полного цикла онбординга (< 3 секунд)|Performance / SLA|E2E (Playwright)|(/) Покрыто (100%)|')
    lines.push('|*NFR-E2E-03*|Надежность: 100% стабильность прохождения тестов без флаки-эффектов|[TC-E2E-01]|Полный приемочный цикл онбординга нового покупателя: регистрация, вход и переход к покупкам|Reliability / Quality|E2E (Playwright)|(/) Покрыто (100%)|')
  } else if (kind === 'e2e') {
    lines.push('* *End-to-End Onboarding Journey:* Полный сквозной путь покупателя покрыт E2E спецификациями TC-E2E-01, TC-E2E-02.')
    lines.push('* *OWASP Session Management:* Контроль хранения JWT-токена в localStorage и отсутствие утечек паролей верифицируется TC-E2E-02.')
    lines.push('* *Error Handling & SLA:* Отображение HTTP 400 ошибок бэкенда на UI и SLA производительности (< 3s) проверяются кейсами TC-E2E-03, TC-E2E-05.')
  } else if (isStory) {
    lines.push('* *End-to-End User Journeys:* Сквозные пути покупателя полностью закрыты E2E BDD спецификациями.')
    lines.push('* *Security Standards:* OWASP Top 10 A03 и управление Bearer сессиями верифицируются сквозным сценарием TC-ST-04.')
    lines.push('* *Data Persistence & Integrity:* Целостность транзакций между клиентом и SQLite базой подтверждается сценариями TC-ST-01, TC-ST-02, TC-ST-03.')
  } else if (isTask) {
    lines.push('* *Reliability & Fault Tolerance:* Устойчивость к сбоям подтверждается негативными проверками TC-TASK-03.')
    lines.push('* *Contract Integrity:* Целостность схемы взаимодействия проверяется кейсом TC-TASK-01.')
    lines.push('* *Security Isolation:* Ограничение прав проверяется кейсом TC-TASK-04.')
  } else {
    lines.push('* *UX & Error Handling:* Все экранные состояния (Default, Loading, Success, Empty, Error) покрыты кейсами JS-57, JS-60, JS-61, JS-68.')
    lines.push('* *Security Standards:* OWASP Session Management & Token Storage верифицируются кейсами JS-61, JS-62, JS-65.')
    lines.push('* *Data Integrity:* Целостность полей ввода и защита от XSS верифицируются на уровне валидации Angular Reactive Forms.')
  }
  lines.push('')
  lines.push('(/) *Заключение QA Lead:* Все требования задачи имеют двустороннюю трассируемость (Bi-directional Traceability) в Qase TMS. Покрытие скоупа составляет 100%.')

  return lines.join('\n')
}

const casesReport = lines.join('\n')
const rtmCommentBody = generateRtmComment(ctx, cases, kind)

const existingComments = ($('Jira: Загрузить данные задачи').first().json.fields?.comment?.comments) || []
const stage3 = existingComments.find(c => c.body && c.body.includes('[Этап 3 из'))
const stage4 = existingComments.find(c => c.body && c.body.includes('[Этап 4 из'))
const jiraBase = 'https://romeo-timony.atlassian.net'

const casesMethod = stage3 ? 'PUT' : 'POST'
const casesUrl = stage3
  ? `${jiraBase}/rest/api/2/issue/${ctx.issueKey}/comment/${stage3.id}`
  : `${jiraBase}/rest/api/2/issue/${ctx.issueKey}/comment`

const rtmMethod = stage4 ? 'PUT' : 'POST'
const rtmUrl = stage4
  ? `${jiraBase}/rest/api/2/issue/${ctx.issueKey}/comment/${stage4.id}`
  : `${jiraBase}/rest/api/2/issue/${ctx.issueKey}/comment`

return [{
  json: {
    issueKey: ctx.issueKey,
    kind: ctx.kind,
    cases,
    qaseCases,
    hasNewCases,
    testDesignIntegrity,
    designGatePassed,
    droppedCases,
    casesReport,
    rtmCommentBody,
    casesMethod,
    casesUrl,
    rtmMethod,
    rtmUrl
  }
}]

